package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraftforge.gametest.*;
/** Declared welfare checkpoints. Actual walking/input lives in the connected client fixture. */
@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TycoonCareGameTests {
    private record Fixture(ServerPlayer p,TycoonData.Home h,BlockPos c,List<TycoonNpc> actors){}
    private static Fixture fixture(GameTestHelper t){var l=t.getLevel().getServer().overworld();var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"CareQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var h=TycoonWorld.home(p);h.state.putBoolean("Activated",true);h.state.putLong("ActiveTicks",5000);var c=t.absolutePos(new BlockPos(2,2,2));
        for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++){l.setBlock(c.offset(x,-1,z),Blocks.OAK_PLANKS.defaultBlockState(),2);for(int y=0;y<5;y++)l.setBlock(c.offset(x,y,z),(y==4||Math.abs(x)==5||Math.abs(z)==5)?Blocks.OAK_PLANKS.defaultBlockState():Blocks.AIR.defaultBlockState(),2);}for(int y=0;y<2;y++)l.setBlock(c.offset(0,y,5),Blocks.AIR.defaultBlockState(),2);var f=new Fixture(p,h,c,new ArrayList<>());put(f,"special_dimension_little_door",c.south(3));put(f,"orphan_bed",c.offset(-2,0,-2));put(f,"orphan_food_table",c);put(f,"orphan_fridge",c.offset(2,0,-2));put(f,"water_station",c.offset(2,0,2));put(f,"orphan_lamp",c.offset(-3,0,1));put(f,"toy_box",c.offset(-2,0,2));var ownBed=c.offset(2,0,3);l.setBlock(ownBed,Blocks.BLUE_BED.defaultBlockState(),2);p.setRespawnPosition(l.dimension(),ownBed,0,false,false);p.setPos(c.south(2).getCenter());return f;}

    @GameTest(template="empty",timeoutTicks=150) public static void recurringWarningAndReputationRemainScheduled(GameTestHelper t){var f=fixture(t);try{f.h.state.putBoolean("EverApproved",true);TycoonAgency.finish(f.p,TycoonRooms.survey(f.p),"Declared missing facilities",false);t.assertFalse(f.h.state.getBoolean("Approved"),"Failed inspection still approves placement");t.assertTrue(f.h.state.getBoolean("EverApproved")&&f.h.state.getLong("NextInspection")==f.h.clock()+24000&&f.h.state.getLong("WarningDeadline")==f.h.clock()+24000,"Warning removed household from inspection roster");t.assertTrue(f.h.reputation()==45,"Failed inspection has no reputation cost");TycoonAgency.finish(f.p,TycoonRooms.survey(f.p),"Declared repaired household",true);t.assertFalse(f.h.state.contains("WarningDeadline"),"Repaired household retained expired warning");t.assertTrue(f.h.state.getLong("NextInspection")>f.h.clock(),"Recurring inspection wasn't rescheduled");}finally{clean(f);}t.succeed();}

    @GameTest(template="empty",timeoutTicks=150) public static void ownerOnlyCareRequestedFoodAndMultipleBedsStaySeparate(GameTestHelper t){var f=fixture(t);try{var first=child(f);var second=child(f);put(f,"orphan_bed",f.c.offset(-2,0,0));second.n.putLong("Bed",f.c.offset(-2,0,0).asLong());t.assertFalse(first.bed().equals(second.bed()),"Distinct residents share a bed assignment");var a=f.actors.get(0);f.p.setPos(a.position().add(0,0,1));first.need("Hunger",20);first.n.putString("Request","ITEM");first.n.putString("Wanted","minecraft:bread");first.n.putBoolean("Accepted",true);f.p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BREAD,2));t.assertTrue(TycoonCare.serve(f.p,a)&&first.n.getString("Request").isEmpty()&&first.need("Hunger")==20&&f.p.getMainHandItem().getCount()==1,"Requested food incorrectly consumed as an unrelated meal");UUID original=a.owner;a.owner=UUID.randomUUID();t.assertFalse(TycoonCare.serve(f.p,a),"Foreign owner can feed/alter this household");a.owner=original;t.assertTrue(second.need("Hunger")==90,"Care changed a different resident's needs");}finally{clean(f);}t.succeed();}
    private static void put(Fixture f,String id,BlockPos at){var l=f.p.server.overworld();l.setBlock(at,TycoonContent.BLOCKS.get(id).get().defaultBlockState(),2);var be=(TycoonBlockEntity)l.getBlockEntity(at);be.owner=f.p.getUUID();be.setChanged();if(id.equals("special_dimension_little_door"))f.h.state.putLong("Entrance",at.asLong());else{var n=f.h.state.getCompound("Furniture");n.putString(Long.toString(at.asLong()),id);f.h.state.put("Furniture",n);}}
    private static TycoonBlockEntity at(Fixture f,BlockPos pos){return (TycoonBlockEntity)f.p.server.overworld().getBlockEntity(pos);}
    private static TycoonData.Resident child(Fixture f){var id=UUID.randomUUID();var r=TycoonCare.generate(id);r.n.putString("Status","ACTIVE");r.n.putLong("Bed",f.c.offset(-2,0,-2).asLong());r.n.putLong("NextRequest",1000000);r.n.putLong("NextIncident",1000000);var a=TycoonContent.NPC.get().create(f.p.server.overworld());a.configure(f.p.getUUID(),id,false,r.n.getInt("Appearance"));a.setPos(f.c.offset(-1,0,-2).getCenter());f.p.server.overworld().addFreshEntity(a);r.n.putUUID("Entity",a.getUUID());f.h.residents.put(id,r);f.actors.add(a);return r;}
    private static void clean(Fixture f){f.actors.forEach(net.minecraft.world.entity.Entity::discard);TycoonData.get(f.p.server).homes.remove(f.p.getUUID());TycoonNetwork.clear(f.p.getUUID());}
    @GameTest(template="empty",timeoutTicks=150) public static void geometryCapacityComfortAndEmptySuppliesMatter(GameTestHelper t){var f=fixture(t);t.runAfterDelay(35,()->{try{var missing=TycoonRooms.survey(f.p);t.assertTrue(missing.capacity()==1,"Real safe Orphan Bed wasn't counted: "+missing.problems());t.assertFalse(missing.approved(),"Empty fridge/water passed inspection");at(f,f.c.offset(2,0,-2)).setItem(0,new ItemStack(Items.BREAD,8));at(f,f.c.offset(2,0,2)).water=8;var valid=TycoonRooms.survey(f.p);t.assertTrue(valid.approved(),"Valid facilities rejected: "+valid.problems());var r=child(f);int before=TycoonRooms.comfort(f.p,r,valid);put(f,"orphan_rug",f.c.offset(-3,0,-2));int after=TycoonRooms.comfort(f.p,r,TycoonRooms.survey(f.p));t.assertTrue(after>before,"Unplaced decoration/real comfort handling wrong");var be=at(f,f.c.offset(-2,0,-2));be.owner=UUID.randomUUID();t.assertTrue(TycoonRooms.survey(f.p).capacity()==0,"Another owner's bed counted");}finally{clean(f);}t.succeed();});}
    @GameTest(template="empty",timeoutTicks=150) public static void realManualAndSelfServiceConsumeSupplies(GameTestHelper t){var f=fixture(t);t.runAfterDelay(35,()->{try{var r=child(f);var a=f.actors.get(0);TycoonNativePlayers.add(f.p);a.setOnGround(true);r.need("Hunger",20);r.need("Neglect",20);f.p.setPos(a.position().add(0,0,1));f.p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BREAD,2));t.assertTrue(TycoonCare.serve(f.p,a)&&f.p.getMainHandItem().getCount()==1&&r.n.contains("Meal")&&r.need("Hunger")==20,"Manual service did not reserve one real item before eating");for(int i=0;i<5;i++)TycoonMeals.tick(f.p,r,a);t.assertTrue(r.need("Hunger")>50&&r.need("Neglect")<20,"Eating completion did not apply quality care");r.n.putLong("MealAfter",0);r.n.putInt("ActionRemaining",0);r.need("Hunger",10);r.need("Thirst",80);r.n.putLong("MealRequest",1000);var fridge=at(f,f.c.offset(2,0,-2));fridge.setItem(0,new ItemStack(Items.BREAD,2));var survey=TycoonRooms.survey(f.p);a.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(java.util.Objects.requireNonNull(TycoonMeals.approach(f.p,a,fridge.getBlockPos()))));TycoonCare.tickOwned(f.p,a);t.assertTrue(r.n.contains("Meal")&&fridge.getItem(0).getCount()==1,"Self-service did not reserve one real food");for(int i=0;i<5;i++)TycoonMeals.tick(f.p,r,a);t.assertTrue(r.n.getBoolean("SelfServed"),"Self-fed quality completion was not recorded");r.n.putInt("ActionRemaining",0);r.need("Thirst",10);r.n.putLong("WaterRequest",1000);var water=at(f,f.c.offset(2,0,2));water.water=8;a.setPos(TycoonRooms.approach(survey.reachable(),water.getBlockPos()).getCenter());TycoonCare.tickOwned(f.p,a);t.assertTrue(water.water==7&&r.need("Thirst")>40,"Water self-service created free supplies");}catch(Throwable failure){failure.printStackTrace();throw failure;}finally{TycoonNativePlayers.remove(f.p);clean(f);}t.succeed();});}
    @GameTest(template="empty",timeoutTicks=150) public static void runawayAndSustainedDeprivationArePersistentUnrewardedOutcomes(GameTestHelper t){var f=fixture(t);t.runAfterDelay(35,()->{try{var r=child(f);var a=f.actors.get(0);r.need("Neglect",100);TycoonCare.tickOwned(f.p,a);t.assertTrue(r.n.getString("Status").equals("RUNAWAY")&&r.bed()==null&&!a.isRemoved(),"Runaway erased NPC instantly or kept active bed");var dead=child(f);var b=f.actors.get(1);dead.need("Hunger",0);dead.need("Thirst",0);dead.n.putInt("CriticalTicks",23980);TycoonCare.tickOwned(f.p,b);t.assertTrue(dead.n.getString("Status").equals("DECEASED")&&!b.isRemoved()&&dead.bed()==null,"Sustained deprivation outcome missing");t.assertTrue(f.h.state.getLong("SoulEssence")==0&&f.h.reputation()<50,"Failure generated profit or no reputation consequence");var snapshot=TycoonData.get(f.p.server).save(new net.minecraft.nbt.CompoundTag());var loaded=TycoonData.load(snapshot).home(f.p.getUUID());t.assertTrue(loaded.residents.get(dead.id).n.getString("Status").equals("DECEASED")&&!loaded.residents.get(r.id).active(),"Outcome tombstones lost on reload");}finally{clean(f);}t.succeed();});}
    @GameTest(template="empty",timeoutTicks=150) public static void placementRejectsUncheckpointedPaymentAndKeepsOwnerCooldown(GameTestHelper t){var f=fixture(t);t.runAfterDelay(35,()->{try{at(f,f.c.offset(2,0,-2)).setItem(0,new ItemStack(Items.BREAD,8));at(f,f.c.offset(2,0,2)).water=8;f.h.state.putBoolean("Approved",true);var choice=TycoonAgency.candidates(f.h).get(0);f.p.getInventory().setItem(0,new ItemStack(Items.EMERALD,20));String result=TycoonPlacements.commit(f.p,choice,f.c.offset(-2,0,-2),f.c.south(2),TycoonAgency.fee(f.h));t.assertTrue(result.startsWith("Placement paused")&&TycoonShop.count(f.p,Items.EMERALD)==20&&f.h.activeResidents()==0&&TycoonPlacements.receipt(f.p)==null&&f.h.state.getCompound("PendingPlacement").hasUUID("Receipt")&&f.h.state.getCompound("PendingPlacement").getCompound("Resident").getUUID("Id").equals(choice.id),"Unlogged fake player bypassed durable payment receipt: "+result);f.h.state.putLong("PlacementAfter",f.h.clock()+72000);t.assertTrue(TycoonAgency.place(f.p,choice.id).contains("active minutes"),"Owner cooldown bypassed");var loaded=TycoonData.load(TycoonData.get(f.p.server).save(new net.minecraft.nbt.CompoundTag())).home(f.p.getUUID());t.assertTrue(loaded.cooldown()==72000&&loaded.residents.isEmpty(),"Reload reset owner cooldown");}finally{clean(f);}t.succeed();});}
}
